import { sendActionReportFeedback } from "../shared/network/io";
import { rulesFetchService } from "../services/RulesFetchService";
import { initializeSentry } from "../shared/config/initializeSentry";
import { logError, logInfo } from "../utils/log";
import { handleCounterIncrement } from "../utils/handleCounterIncrement";
import { updateTabIcon } from "../utils/updateTabIcon";
import { normalizeUrl } from "../utils/normalizeUrl";
import { isCookieBlockerEnabled } from "../utils/isCookieBlockerEnabled";
import { isDomainResolved } from "../utils/isDomainResolved";
import { updateDefaultActionIconColorMode } from "../utils/updateDefaultActionIconColorMode";
import { isBlockedDomain } from "../utils/isBlockedDomain";
import { findMatchingRule } from "../utils/findMatchingRule";

export const initServiceWorker = () => {
  // Handle installation and startup events
  chrome.runtime.onInstalled.addListener(async () => {
    logInfo("Extension successfully installed!");
    initializeSentry();
    updateDefaultActionIconColorMode();

    // Load rules on installation
    try {
      await rulesFetchService.loadAllRules();
    } catch (error) {
      logError("Error loading rules on installation:", error);
    }

    // Set up alarm for periodic sync
    chrome.alarms.create('sync-rules', { periodInMinutes: 60 });

    // Update all existing tabs on installation
    const tabs = await chrome.tabs.query({});
    for (const tab of tabs) {
      if (tab.id && tab.url) {
        await updateTabIcon(tab.id, tab.url);
      }
    }
  });

  chrome.runtime.onStartup.addListener(async () => {
    logInfo("Extension started!");
    initializeSentry();
    updateDefaultActionIconColorMode();

    // Load cached rules on startup
    try {
      await rulesFetchService.getCachedRules();
    } catch (error) {
      logError("Error loading cached rules on startup:", error);
    }

    // Update all existing tabs on startup
    const tabs = await chrome.tabs.query({});
    for (const tab of tabs) {
      if (tab.id && tab.url) {
        await updateTabIcon(tab.id, tab.url);
      }
    }
  });

  // Update icon when tab changes
  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
    updateDefaultActionIconColorMode();

    // Update icon whenever we have a URL, not just on complete
    if (tab.url && (changeInfo.status || changeInfo.url)) {
      await updateTabIcon(tabId, tab.url);
    }
  });

  // Update icon when tab becomes active
  chrome.tabs.onActivated.addListener(async (activeInfo) => {
    try {
      const tab = await chrome.tabs.get(activeInfo.tabId);
      if (activeInfo.tabId && tab.url) {
        await updateTabIcon(activeInfo.tabId, tab.url);
      }
    } catch (error) {
      // Tab might have been closed before we could get it
      console.debug(`Tab ${activeInfo.tabId} no longer exists:`, error);
    }
  });

  // Update icon when new tab is created
  chrome.tabs.onCreated.addListener(async (tab) => {
    if (tab.id && tab.url) {
      await updateTabIcon(tab.id, tab.url);
    }
  });

  // Update all tabs when extension state changes
  chrome.storage.onChanged.addListener(async (changes, namespace) => {
    if (namespace === "local" && changes.cookieBlockerEnabled) {
      // Update default action icon
      await updateDefaultActionIconColorMode();

      // Update all tabs
      const tabs = await chrome.tabs.query({});
      for (const tab of tabs) {
        if (tab.id && tab.url) {
          await updateTabIcon(tab.id, tab.url);
        }
      }
    }
  });

  // Handle alarm for periodic rules sync
  chrome.alarms.onAlarm.addListener(async (alarm) => {
    if (alarm.name === 'sync-rules') {
      logInfo("Running scheduled rules sync");
      try {
        await rulesFetchService.checkAndSync();
      } catch (error) {
        logError("Error during scheduled sync:", error);
      }
    }
  });

  chrome.runtime.onMessage.addListener(
    async (message, sender, sendResponse) => {
      if (sender?.tab?.id === undefined) {
        logError("Sender tab id is undefined");
        return;
      }

      // Only process requests from the main frame (frameId: 0)
      if (sender.frameId !== 0) {
        logInfo(
          `Ignoring getBannerActionRules from non-main frame (frameId: ${sender.frameId}) in tab ${sender.tab?.id}`
        );
        return;
      }

      if (!message || !message.action) {
        logInfo("No Service Worker action in message. Ignoring.");
        return;
      }
      const isEnabled = await isCookieBlockerEnabled();
      if (!isEnabled) {
        logInfo("Cookie blocker is disabled. Not processing message.");
        return;
      }

      const isResolved = await isDomainResolved(message.url);
      if (isResolved) {
        logInfo("Domain is already resolved. Not processing message.");
        updateTabIcon(sender.tab.id, message.url);
        return;
      }

      const isDomainBlocked = isBlockedDomain(message.url);
      if (isDomainBlocked) {
        logInfo(
          `Domain ${message.url} is excluded. Not processing message.`
        );
        return;
      }

      logInfo("Handling service worker onMessage", { message });

      switch (message.action) {
        case "getBannerActionRules": {
          const cachedRules = await rulesFetchService.getCachedRules();
          logInfo(" ### Rules loaded from cache ###");

          const normalizedUrl = normalizeUrl(message.url);
          logInfo(" ### normalizedUrl ###", normalizedUrl);

          // Find matching rule for the domain (including parent domain matching)
          const actions = findMatchingRule(normalizedUrl, cachedRules.rules.siteSpecific);
          logInfo(" ### actions ###", actions);

          if (actions && actions.length > 0) {
            logInfo(` ### rule found for: ${normalizedUrl} ###`);
            await chrome.tabs.sendMessage(sender.tab.id, {
              action: "click_all",
              clicks: actions,
            });
          } else {
            logInfo(` !!! rule not found for: ${normalizedUrl} !!!`);
            await chrome.tabs.sendMessage(sender.tab.id, {
              action: "search_managing_platforms",
              searchRules: cachedRules.rules.cmp,
            });
          }
          break;
        }

        case "sendReport": {
          try {
            const data = message.data;
            const url = String(message.url);
            logInfo(` ### sending report for: (${new URL(url).hostname}) ###`);
            logInfo("Report data:", data);
            logInfo("Report has errors:", data.errors.length > 0);

            // Increment counter if the report has no errors
            // Pass tabId directly to avoid unreliable URL-based tab queries
            await handleCounterIncrement(data, url, sender.tab.id);

            // Process the report
            await sendActionReportFeedback(data);

            // Send response
            sendResponse({ success: true });
          } catch (error) {
            logError("sendReport error:", error);
            const errorMessage =
              error instanceof Error ? error.message : String(error);
            sendResponse({ success: false, error: errorMessage });
          }
          break;
        }
      }
      return true; // Indicates async response
    }
  );
};
