import { isDarkMode } from "./isDarkMode";
import { logError, logInfo } from "./log";

export const setCheckTabIcon = async (tabId: number, url: string) => {
  try {
    await chrome.action.setIcon({
      tabId: tabId,
      path: {
        16: "icons/green-check.png",
        32: "icons/green-check32.png",
      },
    });
    logInfo(`Icon updated to big green check for tab ${tabId} (${url})`);

    setTimeout(async () => {
      try {
        const isDark = await isDarkMode();
        const darkModeSuffix = isDark ? "-darkmode" : "";

        await chrome.action.setIcon({
          tabId: tabId,
          path: {
            16: `icons/icon-green-check${darkModeSuffix}.png`,
            32: `icons/icon-green-check32${darkModeSuffix}.png`,
          },
        });
        logInfo(`Icon transitioned to green cookie badge for tab ${tabId}`);
      } catch (error) {
        logError(`Failed to transition icon for tab ${tabId}:`, error);
      }
    }, 1000);
  } catch (error) {
    logError(`Failed to update icon for tab ${tabId}:`, error);
  }
};
