import { isCookieBlockerEnabled } from "./isCookieBlockerEnabled";
import { isDarkMode } from "./isDarkMode";
import { isDomainResolved } from "./isDomainResolved";
import { logError } from "./log";

export const updateTabIcon = async (tabId: number, url: string) => {
  try {
    const isEnabled = await isCookieBlockerEnabled();
    const isDark = await isDarkMode();
    const darkModeSuffix = isDark ? "-darkmode" : "";
    
    // Always show gray icon when extension is disabled
    if (!isEnabled) {
      await chrome.action.setIcon({
        tabId: tabId,
        path: {
          "16": `icons/icon-gray-check.png`,
          "32": `icons/icon-gray-check32.png`,
        },
      });
      return;
    }

    const isResolved = await isDomainResolved(url);
    if (isResolved) {
      await chrome.action.setIcon({
        tabId: tabId,
        path: {
          "16": `icons/icon-green-check${darkModeSuffix}.png`,
          "32": `icons/icon-green-check32${darkModeSuffix}.png`,
        },
      });
      return;
    }

    await chrome.action.setIcon({
      tabId: tabId,
      path: {
        "16": `icons/icon-blue-check${darkModeSuffix}.png`,
        "32": `icons/icon-blue-check32${darkModeSuffix}.png`,
      },
    });
  } catch (error) {
    logError("Error updating tab icon:", error);
  }
};
