import { z } from "zod";

const ActionSchema = z.object({
  selector: z.string(),
  tagName: z.string(),
  attributes: z.record(z.string()),
  iframeName: z.string().optional(),
  iframeUrl: z.string().optional(),
});

const RuleSchema = z.object({
  actions: z.array(ActionSchema),
});

const RulesStructureSchema = z.object({
  timestamp: z.number(),
  popularPages: z.record(z.string(), RuleSchema),
  cmps: z.array(z.any()),
});

// Define the RulesStructure type based on the Zod schema
export type RulesStructure = z.infer<typeof RulesStructureSchema>;

// Function to validate the rules
export const validateLocalRules = (rules: unknown): RulesStructure => {
  return RulesStructureSchema.parse(rules);
};
