import { rulesFetchService } from "../services/RulesFetchService";
import { normalizeUrl } from "./normalizeUrl";

export const isBlockedDomain = (url: string): boolean => {
  const normalizedDomain = normalizeUrl(url);
  if (!normalizedDomain) {
    return false;
  }

  const excludedDomains = rulesFetchService.getExcludedDomainsSet();
  return excludedDomains.has(normalizedDomain);
};