import { logError, logInfo } from "../utils/log";
import { rulesConfig } from "../shared/config/config";
import { RuleAction, RuleAttribute, ActionsWithRules } from "../contentScript/RuleAction";

export interface CmpRule {
  type: string;
  regexes: string[];
  rules: ActionsWithRules[];
}

export interface SiteSpecificRule {
  actions: RuleAction[];
  includeSubdomains?: boolean;
}

export interface SiteSpecificRules {
  [domain: string]: SiteSpecificRule;
}

export interface RulesData {
  cmp: CmpRule[];
  excluded: string[];
  siteSpecific: SiteSpecificRules;
}

export interface RulesMetadata {
  versions: {
    cmp?: string;
    excluded?: string;
    siteSpecific?: string;
  };
  lastUpdated: number;
  updateSchedule: {
    cmp: number;
    excluded: number;
    siteSpecific: number;
  };
}

export interface CachedRules {
  rules: RulesData;
  rulesMetadata: RulesMetadata;
}

class RulesFetchService {
  private static instance: RulesFetchService;
  private memoryCache: CachedRules | null = null;
  private excludedDomainsCache: Set<string> = new Set();

  // Default empty rules to use before first load
  private defaultRules: CachedRules = {
    rules: {
      cmp: [],
      excluded: [],
      siteSpecific: {}
    },
    rulesMetadata: {
      versions: {
        cmp: undefined,
        excluded: undefined,
        siteSpecific: undefined
      },
      lastUpdated: 0,
      updateSchedule: {
        cmp: 0,
        excluded: 0,
        siteSpecific: 0
      }
    }
  };

  private constructor() {}

  static getInstance(): RulesFetchService {
    if (!RulesFetchService.instance) {
      RulesFetchService.instance = new RulesFetchService();
    }
    return RulesFetchService.instance;
  }

  private async fetchRules(filename: string): Promise<unknown> {
    const url = `${rulesConfig.baseUrl}${filename}`;

    logInfo(`Fetching rules from: ${url}`);
    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`Failed to fetch ${filename}: ${response.status}`);
    }

    const data = await response.json();
    logInfo(`Successfully fetched ${filename}`);
    return data;
  }

  async loadExpiredRules(existingCache: CachedRules, expiredRules: string[]): Promise<CachedRules> {
    logInfo(`Loading expired rules: ${expiredRules.join(', ')}`);

    // Start with existing rules as base
    const rules: RulesData = { ...existingCache.rules };
    const versions = { ...existingCache.rulesMetadata.versions };

    // Only fetch rules that have expired
    if (expiredRules.includes('cmp')) {
      const cmpRules = await this.fetchRulesWithFallback(
        rulesConfig.files.cmp,
        { cmps: existingCache.rules.cmp }
      );
      rules.cmp = this.transformCmpRules(cmpRules.cmps || []);
      if (cmpRules.id) {
        versions.cmp = cmpRules.id;
      }
      logInfo("Updated CMP rules");
    }

    if (expiredRules.includes('excluded')) {
      const excludedDomains = await this.fetchRulesWithFallback(
        rulesConfig.files.excluded,
        { pages: existingCache.rules.excluded }
      );
      rules.excluded = excludedDomains.pages || [];
      if (excludedDomains.id) {
        versions.excluded = excludedDomains.id;
      }
      this.excludedDomainsCache = new Set(rules.excluded);
      logInfo("Updated excluded domains");
    }

    if (expiredRules.includes('siteSpecific')) {
      const siteSpecificRules = await this.fetchRulesWithFallback(
        rulesConfig.files.siteSpecific,
        { rules: existingCache.rules.siteSpecific }
      );
      rules.siteSpecific = this.transformSiteRules(siteSpecificRules.rules || {});
      if (siteSpecificRules.id) {
        versions.siteSpecific = siteSpecificRules.id;
      }
      logInfo("Updated site-specific rules");
    }

    // Calculate new update schedule with only expired rules updated
    const newUpdateSchedule = this.calculatePartialUpdateSchedule(existingCache.rulesMetadata.updateSchedule, expiredRules);

    const metadata: RulesMetadata = {
      versions,
      lastUpdated: Date.now(),
      updateSchedule: newUpdateSchedule
    };

    const cachedRules: CachedRules = { rules, rulesMetadata: metadata };

    await this.saveToCache(cachedRules);
    this.memoryCache = cachedRules;

    return cachedRules;
  }

  async loadAllRules(): Promise<CachedRules> {
    // Use memory cache as fallback if available, null otherwise to trigger local rules fallback
    const fallback = this.memoryCache;

    // Fetch each rule type individually with fallback on failure
    const cmpRules = await this.fetchRulesWithFallback(
      rulesConfig.files.cmp,
      fallback ? { cmps: fallback.rules.cmp } : null
    );

    const excludedDomains = await this.fetchRulesWithFallback(
      rulesConfig.files.excluded,
      fallback ? { pages: fallback.rules.excluded } : null
    );

    const siteSpecificRules = await this.fetchRulesWithFallback(
      rulesConfig.files.siteSpecific,
      fallback ? { rules: fallback.rules.siteSpecific } : null
    );

    // Transform site-specific rules to match expected format
    const transformedSiteRules = this.transformSiteRules(siteSpecificRules.rules || {});

    const rules: RulesData = {
      cmp: this.transformCmpRules(cmpRules.cmps || []),
      excluded: excludedDomains.pages || [],
      siteSpecific: transformedSiteRules
    };

    const metadata: RulesMetadata = {
      versions: {
        cmp: cmpRules.id,
        excluded: excludedDomains.id,
        siteSpecific: siteSpecificRules.id
      },
      lastUpdated: Date.now(),
      updateSchedule: this.calculateUpdateSchedule()
    };

    const cachedRules: CachedRules = { rules, rulesMetadata: metadata };

    await this.saveToCache(cachedRules);
    this.memoryCache = cachedRules;
    this.excludedDomainsCache = new Set(rules.excluded);

    return cachedRules;
  }

  private async fetchLocalRules(filename: string): Promise<unknown> {
    const url = chrome.runtime.getURL(`rules/${filename}.json`);
    logInfo(`Fetching local rules from: ${url}`);
    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`Failed to fetch local ${filename}: ${response.status}`);
    }

    const data = await response.json();
    logInfo(`Successfully fetched local ${filename}`);
    return data;
  }

  private async fetchRulesWithFallback(filename: string, fallback: any | null): Promise<any> {
    try {
      return await this.fetchRules(filename);
    } catch (error) {
      logError(`Failed to fetch ${filename} from remote:`, error);
    }

    if (fallback) {
      logInfo(`Using cached data for ${filename}`);
      return fallback;
    }

    try {
      logInfo(`No cached data for ${filename}, trying local rules`);
      return await this.fetchLocalRules(filename);
    } catch (error) {
      logError(`Failed to fetch ${filename} from local:`, error);
      return {};
    }
  }

  private transformSiteRules(rawRules: unknown): SiteSpecificRules {
    const transformed: SiteSpecificRules = {};

    if (!rawRules || typeof rawRules !== 'object') {
      return transformed;
    }

    for (const [domain, rule] of Object.entries(rawRules as Record<string, unknown>)) {
      if (!rule || typeof rule !== 'object' || !('actions' in rule)) {
        continue;
      }

      const rawRule = rule as { actions: unknown[]; includeSubdomains?: boolean };
      if (!Array.isArray(rawRule.actions)) {
        continue;
      }

      const transformedActions: RuleAction[] = rawRule.actions
        .map((action: unknown) => this.transformAction(action))
        .filter((action): action is RuleAction => action !== null);

      // Only add if we have at least one valid action
      if (transformedActions.length > 0) {
        transformed[domain] = {
          actions: transformedActions,
          includeSubdomains: rawRule.includeSubdomains
        };
      }
    }

    return transformed;
  }

  private transformCmpRules(rawCmps: unknown[]): CmpRule[] {
    if (!Array.isArray(rawCmps)) return [];

    return rawCmps.map((cmp: any) => ({
      type: cmp.type || '',
      regexes: cmp.regexes || [],
      rules: (cmp.rules || []).map((rule: any) => ({
        actions: (rule.actions || [])
          .map((action: unknown) => this.transformAction(action))
          .filter((action: RuleAction | null): action is RuleAction => action !== null)
      }))
    }));
  }

  private transformAction(action: unknown): RuleAction | null {
    if (!action || typeof action !== 'object') {
      return null;
    }

    const actionObj = action as Record<string, unknown>;
    let selector = '';
    let tagName = '';
    let attributes: RuleAttribute = {};

    // Handle nested element structure from popular_rules.json
    if ('element' in actionObj && actionObj.element) {
      const element = actionObj.element as Record<string, unknown>;
      selector = actionObj.selector as string || '';
      tagName = (element.tag_name || element.tagName) as string || '';
      attributes = this.transformAttributes((element.attributes || {}) as Record<string, any>);
    } else {
      // Handle flat structure
      selector = actionObj.selector as string || '';
      tagName = actionObj.tagName as string || '';
      attributes = this.transformAttributes((actionObj.attributes || {}) as Record<string, any>);
    }

    // Validate required fields
    if (!selector || !tagName) {
      logError(`Invalid action: missing selector or tagName`, { selector, tagName });
      return null;
    }

    return {
      selector,
      tagName,
      attributes,
      iframeName: actionObj.iframeName as string | undefined,
      iframeUrl: actionObj.iframeUrl as string | undefined
    };
  }

  private transformAttributes(attrs: Record<string, any>): RuleAttribute {
    if (!attrs || typeof attrs !== 'object') {
      return {};
    }

    const transformed: RuleAttribute = {};
    for (const [key, value] of Object.entries(attrs)) {
      if (value === null || value === undefined) {
        continue;
      }
      // Transform class_ to class
      const newKey = key === 'class_' ? 'class' : key;
      // Only convert to string if it's not already
      transformed[newKey] = typeof value === 'string' ? value : String(value);
    }
    return transformed;
  }

  private calculateUpdateSchedule(): RulesMetadata['updateSchedule'] {
    const now = Date.now();
    const dailyInterval = 24 * 60 * 60 * 1000;

    return {
      cmp: now + dailyInterval,
      excluded: now + dailyInterval,
      siteSpecific: now + dailyInterval
    };
  }

  private calculatePartialUpdateSchedule(existingSchedule: RulesMetadata['updateSchedule'], updatedRules: string[]): RulesMetadata['updateSchedule'] {
    const now = Date.now();
    const dailyInterval = 24 * 60 * 60 * 1000;

    return {
      cmp: updatedRules.includes('cmp') ? now + dailyInterval : existingSchedule.cmp,
      excluded: updatedRules.includes('excluded') ? now + dailyInterval : existingSchedule.excluded,
      siteSpecific: updatedRules.includes('siteSpecific') ? now + dailyInterval : existingSchedule.siteSpecific
    };
  }

  async getCachedRules(): Promise<CachedRules> {
    if (this.memoryCache) {
      return this.memoryCache;
    }

    const cached = await this.loadFromCache();

    const updateCheck = this.shouldUpdate(cached.rulesMetadata);
    if (updateCheck.shouldUpdate) {
      logInfo(`Rules need update for: ${updateCheck.expiredRules.join(', ')}, fetching fresh rules`);
      return this.loadExpiredRules(cached, updateCheck.expiredRules);
    }

    this.memoryCache = cached;
    this.excludedDomainsCache = new Set(cached.rules.excluded);
    return cached;
  }

  private shouldUpdate(metadata: RulesMetadata): { shouldUpdate: boolean; expiredRules: string[] } {
    const now = Date.now();
    const { cmp, excluded, siteSpecific } = metadata.updateSchedule;
    const expiredRules: string[] = [];

    if (now > cmp) expiredRules.push('cmp');
    if (now > excluded) expiredRules.push('excluded');
    if (now > siteSpecific) expiredRules.push('siteSpecific');

    return {
      shouldUpdate: expiredRules.length > 0,
      expiredRules
    };
  }

  private async saveToCache(data: CachedRules): Promise<void> {
    try {
      await chrome.storage.local.set(data);
      logInfo("Rules saved to chrome.storage.local");
    } catch (error) {
      logError("Error saving to chrome.storage.local:", error);
    }
  }

  private async loadFromCache(): Promise<CachedRules> {
    try {
      const result = await chrome.storage.local.get(["rules", "rulesMetadata"]);

      if (!result.rules || !result.rulesMetadata) {
        logInfo("No cached rules found, fetching from backend");
        return this.loadAllRules();
      }

      logInfo("Loaded rules from chrome.storage.local");
      return {
        rules: result.rules as RulesData,
        rulesMetadata: result.rulesMetadata as RulesMetadata
      };
    } catch (error) {
      logError("Error loading from chrome.storage.local:", error);
      logInfo("Attempting to fetch fresh rules");
      return this.loadAllRules();
    }
  }

  async checkAndSync(): Promise<void> {
    try {
      const cached = await this.loadFromCache();

      const updateCheck = this.shouldUpdate(cached.rulesMetadata);
      if (updateCheck.shouldUpdate) {
        logInfo(`Syncing expired rules from backend: ${updateCheck.expiredRules.join(', ')}`);
        await this.loadExpiredRules(cached, updateCheck.expiredRules);
      } else {
        logInfo("Rules are up to date");
      }
    } catch (error) {
      logError("Error checking and syncing rules:", error);
    }
  }

  getExcludedDomainsSet(): Set<string> {
    return this.excludedDomainsCache;
  }

  getSiteSpecificRule(domain: string): SiteSpecificRule | null {
    const cache = this.memoryCache || this.defaultRules;
    return cache.rules.siteSpecific[domain] || null;
  }

  getCmpRules(): CmpRule[] {
    const cache = this.memoryCache || this.defaultRules;
    return cache.rules.cmp;
  }
}

export const rulesFetchService = RulesFetchService.getInstance();
