import {
  ActionsReport,
  ActionReportItem,
  ActionReportType,
} from "../contentScript/sendActionsReport";
import { incTotalPagesResolved } from "./incTotalPagesResolved";
import { logInfo, logError } from "./log";
import { setCheckTabIcon } from "./setCheckedTabIcon";
import { storeResolvedDomain } from "./storeResolvedDomain";
import { normalizeUrl } from "./normalizeUrl";

export const handleCounterIncrement = async (
  data: ActionsReport,
  url: string,
  tabId?: number
): Promise<void> => {
  // Guard clause 1: Exit if there are errors or no actions
  if (data.errors.length > 0 || !data.actions || data.actions.length === 0) {
    logInfo("No valid actions to process");
    return;
  }
  try {
    // Determine if we should increment based on report type
    const isManagementPlatform =
      data.type === ActionReportType.COOKIE_MANAGEMENT_PLATFORM;
    const shouldIncrement = isManagementPlatform
      ? data.actions.some((action: ActionReportItem) => action.clicked)
      : data.actions.some(
          (action: ActionReportItem) => action.elementsFound > 0
        );

    // Guard clause 2: Exit if no elements were interacted with
    if (!shouldIncrement) {
      logInfo("No elements were interacted with, not incrementing counter");
      return;
    }

    // Guard clause 3: Exit if no URL provided
    if (!url) {
      logInfo("No URL provided, cannot update icon or store domain");
      return;
    }

    // Update tab icon - use tabId directly if provided, otherwise fall back to URL query
    if (tabId) {
      await setCheckTabIcon(tabId, url);
    } else {
      await callSetCheckTabIcon(url);
    }

    // Store resolved domain
    await storeResolvedDomain(url);

    // Increment counter
    const newTotal = await incTotalPagesResolved();
    logInfo("Counter incremented to:", newTotal);
  } catch (error) {
    logError("Error in handleCounterIncrement:", error);
  }
};

// Helper function to update tab icon
const callSetCheckTabIcon = async (url: string): Promise<void> => {
  try {
    // First try exact URL match
    const tabs = await chrome.tabs.query({ url });

    if (tabs.length > 0) {
      // Update matching tabs
      for (const tab of tabs) {
        if (tab.id) {
          await setCheckTabIcon(tab.id, url);
        }
      }
      return;
    }

    // If exact match fails, try domain match
    const normalizedUrl = normalizeUrl(url);
    const allTabs = await chrome.tabs.query({});

    for (const tab of allTabs) {
      if (tab.id && tab.url && tab.url.includes(normalizedUrl)) {
        await setCheckTabIcon(tab.id, url);
      }
    }
  } catch (error) {
    logError("Error updating tab icon:", error);
  }
};
