import { logError, logInfo } from "./log";
import { normalizeUrl } from "./normalizeUrl";

// Helper function to store resolved domain
export const storeResolvedDomain = async (url: string): Promise<void> => {
  try {
    const normalizedDomain = normalizeUrl(url);
    if (!normalizedDomain) {
      logInfo("No valid domain to store", url);
      return;
    }

    // Store the domain in session storage
    const resolvedDomainsResult = await chrome.storage.session.get([
      "resolvedDomains",
    ]);
    const resolvedDomains = resolvedDomainsResult.resolvedDomains || [];

    if (!resolvedDomains.includes(normalizedDomain)) {
      resolvedDomains.push(normalizedDomain);
      await chrome.storage.session.set({ resolvedDomains });
      logInfo(`Domain ${normalizedDomain} added to resolved domains`);
    }
  } catch (error) {
    logError("Error storing resolved domain:", error);
  }
};
