import { logError } from "./log";

type TrackingParams = {
  event_category: "banner" | "platform";
  event_action: "error" | "processed";
};

export const track = (params: TrackingParams) => {
  const windowChrome = chrome as any;
  const stats = windowChrome?.avast?.stats;

  if (!stats) {
    logError("avast.stats is not available");
    return;
  }

  const commonData = {
    "group.extension.version": chrome.runtime.getManifest().version,
    "group.extension.id": chrome.runtime.id,
    page_domain: "cookie_guard",
  };

  const eventData = {
    ...params,
    ...commonData,
  };

  stats.add("event", eventData);
};
