import { RuleAction } from "../contentScript/RuleAction";

interface RuleConfig {
  actions: RuleAction[];
  includeSubdomains?: boolean;
}

interface PopularPages {
  [domain: string]: RuleConfig;
}

/**
 * Finds a matching rule for a given domain, checking exact match first,
 * then parent domains if subdomain matching is enabled (default behavior).
 * 
 * @param domain - The domain to find rules for (e.g., "visualstudio.microsoft.com")
 * @param popularPages - The rules configuration object
 * @returns The actions array if a match is found, null otherwise
 */
export const findMatchingRule = (
  domain: string,
  popularPages: PopularPages | undefined | null
): RuleAction[] | null => {
  if (!domain || !popularPages) {
    return null;
  }

  // Clean up the domain (remove trailing dots)
  const cleanDomain = domain.replace(/\.$/, '');
  
  // First check for exact match (highest priority)
  if (popularPages[cleanDomain]) {
    return popularPages[cleanDomain].actions || null;
  }

  // Split domain into parts for parent domain checking
  const domainParts = cleanDomain.split('.');
  
  // Need at least 2 parts for a valid domain (e.g., "example.com")
  if (domainParts.length < 2) {
    return null;
  }

  // Check parent domains from most specific to least specific
  // For "v2.api.ft.com", check: "api.ft.com", then "ft.com"
  for (let i = 1; i < domainParts.length - 1; i++) {
    const parentDomain = domainParts.slice(i).join('.');
    const ruleConfig = popularPages[parentDomain];
    
    if (ruleConfig) {
      // Check if subdomains are included (default is true)
      const includeSubdomains = ruleConfig.includeSubdomains !== false;
      
      if (includeSubdomains) {
        return ruleConfig.actions || null;
      }
    }
  }

  return null;
};